INSERT INTO `projects` VALUES
(180001,'Full-Stack Dynamic Portfolio & CMS','The Problem: Static portfolios require manual code changes for every update, which is inefficient and error-prone. The Solution: Engineered a custom Content Management System (CMS) using Node.js, Express, and MySQL. Implemented a \"Render-Aware\" automation engine with Puppeteer to handle cold-start delays and capture real-time project screenshots. The Impact: Reduced project update time by 90% and eliminated manual image management through automated screenshot generation and filesystem garbage collection','https://franciskienji.vercel.app/','https://github.com/FranNMK/Super_finalportifolio.git',2026,'https://res.cloudinary.com/dbvfxqeem/image/upload/v1777225828/portfolio_projects/project_180001.png',13,0,NULL,'2026-04-26 17:50:13'),
(300003,'EduPay Africa','EduPay Africa is a continent-wide school payment platform designed specifically for African educational institutions. Starting in Kenya and expanding across Africa, the platform simplifies fee collection, management, and reconciliation for schools while providing parents with a seamless payment experience.','https://edupay-africa.onrender.com','https://github.com/FranNMK/EduPayAfrica.git',2027,'https://res.cloudinary.com/dbvfxqeem/image/upload/v1777230983/portfolio_projects/project_300003.png',31,0,NULL,'2026-04-26 19:15:50');
